import Cropper from 'cropperjs';
import axios from 'axios';
import qs from 'qs';
import { sprintf } from 'sprintf-js';

(function($) {
  var field = null;

  function aiarcRestUrls() {
    const urls = (window.aiarc && window.aiarc.rest_urls) || {};
    const root = (window.aiarc && window.aiarc.api_root) || '';
    return {
      upload: urls.upload || `${root}/aiarc/v1/upload`,
      crop: urls.crop || `${root}/aiarc/v1/crop`,
      get: urls.get || `${root}/aiarc/v1/get`,
      preview: urls.preview || window.aiarc.preview_rest_url || `${root}/aiarc/v1/preview`,
    };
  }

  function aiarcBuildPreviewUrl(data) {
    const c = data.crop || {};
    const nonce = window.aiarc.preview_nonce || window.aiarc.wp_rest_nonce || '';
    const ajaxBase =
      window.aiarc.preview_ajax_url ||
      (typeof ajaxurl !== 'undefined' ? ajaxurl : '');
    const base = ajaxBase || aiarcRestUrls().preview;
    const separator = base.indexOf('?') >= 0 ? '&' : '?';
    const actionPrefix =
      ajaxBase && base.indexOf('action=aiarc_preview') < 0
        ? 'action=aiarc_preview&'
        : '';
    const previewUrl = `${base}${separator}${actionPrefix}id=${data.attachment_id}&x=${c.x}&y=${c.y}&w=${c.width}&h=${c.height}&_wpnonce=${nonce}`;
    // #region agent log
    fetch('http://127.0.0.1:7743/ingest/9f827881-a6d4-4dd9-ad99-4d8dfb5ed04f', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Debug-Session-Id': '7d3f1f',
      },
      body: JSON.stringify({
        sessionId: '7d3f1f',
        hypothesisId: 'H2',
        location: 'input.js:aiarcBuildPreviewUrl',
        message: 'built preview URL',
        data: {
          previewUrl,
          usesAjax: Boolean(ajaxBase),
          preview_ajax_url: window.aiarc.preview_ajax_url || null,
        },
        timestamp: Date.now(),
      }),
    }).catch(() => {});
    // #endregion
    return previewUrl;
  }

  acf.fields.image_aspect_ratio_crop = acf.field.extend({
    type: 'image_aspect_ratio_crop',
    $el: null,
    $input: null,
    $img: null,

    actions: {
      ready: 'initialize',
      append: 'initialize',
    },

    events: {
      'click a[data-name="add"]': 'add',
      'click a[data-name="edit"]': 'edit',
      'click a[data-name="remove"]': 'remove',
      'change input[type="file"]': 'change',
      'click a[data-name="crop"]': 'changeCrop',
      'change .js-aiarc-upload': 'front_end_upload',
    },

    front_end_upload: function(event) {
      let uploadElement = event.currentTarget;

      var acfKey = $(this.$field)
        .find('.acf-image-uploader-aspect-ratio-crop')
        .data('key');

      let files = uploadElement.files;
      let formData = new FormData();

      this.isFirstCrop = true;

      if (!files.length) {
        return;
      }

      Array.from(Array(files.length).keys()).map(index => {
        formData.append('image', files[index], files[index].name);
        formData.append('key', acfKey);
      });

      uploadElement.value = '';

      let settings = {
        onUploadProgress: progressEvent => {
          let percentCompleted = Math.round(
            (progressEvent.loaded * 100) / progressEvent.total,
          );

          this.$el
            .find('.js-aiarc-upload-progress')
            .html(
              sprintf(
                window.aiarc_translations.upload_progress,
                percentCompleted,
              ),
            );
        },
        headers: {
          'X-Aiarc-Nonce': window.aiarc.nonce,
          'X-WP-Nonce': window.aiarc.wp_rest_nonce,
        },
      };

      $(this.$el)
        .find('.js-aiarc-upload')
        .hide();

      $(this.$el)
        .find('.js-aiarc-upload-progress')
        .show();

      axios
        .post(`${aiarcRestUrls().upload}`, formData, settings)
        .then(response => {
          // This is just for the preview
          axios
            .get(
              `${aiarcRestUrls().get}/${response.data.attachment_id}`,
            )
            .then(response => {
              let attachment = new window.Backbone.Model(response.data);
              this.render(attachment);
            });

          $(this.$el)
            .find('.js-aiarc-upload-progress')
            .hide();

          $(this.$el)
            .find('.js-aiarc-upload')
            .show();

          let $field = this.$field;

          // Add original id attribute to the image so we can recrop it right away without saving the post
          $field
            .find('.acf-image-uploader-aspect-ratio-crop')
            .data('original-image-id', response.data.attachment_id)
            .attr('data-original-image-id', response.data.attachment_id);

          axios
            .get(
              `${aiarcRestUrls().get}/${response.data.attachment_id}`,
            )
            .then(response => {
              let attachment = new window.Backbone.Model(response.data);

              this.render(attachment);
              this.openModal({ attachment: attachment, field: $field });
            });
        })
        .catch(error => {
          $(this.$el)
            .find('.js-aiarc-upload-progress')
            .hide();

          $(this.$el)
            .find('.js-aiarc-upload')
            .show();

          let errorMessage = window.aiarc_translations.upload_failed;

          if (
            error.response &&
            error.response.data &&
            error.response.data.message
          ) {
            errorMessage = error.response.data.message;
          }

          window.alert(errorMessage);
        });
    },

    /*
     *  focus
     *
     *  This function will setup variables when focused on a field
     *
     *  @type	function
     *  @date	12/04/2016
     *  @since	5.3.8
     *
     *  @param	n/a
     *  @return	n/a
     */

    focus: function() {
      // vars
      this.$el = this.$field.find('.acf-image-uploader-aspect-ratio-crop');
      this.$input = this.$el.find('input[type="hidden"]');
      this.$img = this.$el.find('img');

      // options
      this.o = acf.get_data(this.$el);
    },

    /*
     *  initialize
     *
     *  This function is used to setup basic upload form attributes
     *
     *  @type	function
     *  @date	12/04/2016
     *  @since	5.3.8
     *
     *  @param	n/a
     *  @return	n/a
     */

    initialize: function() {
      this.isFirstCrop = null;
      var self = this;

      // add attribute to form
      if (this.o.uploader == 'basic') {
        this.$el.closest('form').attr('enctype', 'multipart/form-data');
      }

      this.escapeHandlerBound = this.escapeHandler.bind(this);

      $(document).on('click', '.js-acf-image-aspect-ratio-crop-cancel', () =>
        this.closeModal(),
      );

      $(document)
        .off('click', '.js-acf-image-aspect-ratio-crop-reset')
        .on('click', '.js-acf-image-aspect-ratio-crop-reset', () => {
          this.cropper.reset();
          this.resetFocalPoint();
        });

      $(document)
        .off('click', '.js-acf-image-aspect-ratio-crop-crop')
        .on('click', '.js-acf-image-aspect-ratio-crop-crop', function() {
          var cropData = self.cropper.getData(true);

          $('.js-acf-image-aspect-ratio-crop-modal').css(
            'max-width',
            self.cropper.containerData.width,
          );

          var cropType = $(field)
            .find('.acf-image-uploader-aspect-ratio-crop')
            .data('crop_type');

          let acfKey = $(field)
            .find('.acf-image-uploader-aspect-ratio-crop')
            .data('key');

          var data = {
            id: $(this).data('id'),
            aspectRatioHeight: $(this).data('aspect-ratio-height'),
            aspectRatioWidth: $(this).data('aspect-ratio-width'),
            cropType: $(this).data('crop-type'),
            x: cropData.x,
            y: cropData.y,
            width: cropData.width,
            height: cropData.height,
            focalPointX: self.focalPoint.x,
            focalPointY: self.focalPoint.y,
            temp_post_id: aiarc.temp_post_id,
            key: acfKey,
          };

          $('.js-acf-image-aspect-ratio-crop-crop').prop('disabled', true);
          $('.js-acf-image-aspect-ratio-crop-reset').prop('disabled', true);

          // prettier-ignore
          var loading = '<div class="acf-image-aspect-ratio-crop-modal-loading">' +
                          '<div class="acf-image-aspect-ratio-crop-modal-loading-icon">' +
                          '<!-- Icon from https://github.com/google/material-design-icons -->' +
                          '<!-- Licensed under Apache License 2.0 -->' +
                          '<!-- Copyright (c) Google Inc. -->' +
                          '<svg width="14" height="14" viewBox="0 0 14 14" xmlns="http://www.w3.org/2000/svg"><path d="M7 2.64V1L4.75 3.18 7 5.36V3.73A3.33 3.33 0 0 1 10.38 7c0 .55-.15 1.07-.4 1.53l.82.8c.44-.68.7-1.47.7-2.33A4.43 4.43 0 0 0 7 2.64zm0 7.63A3.33 3.33 0 0 1 3.62 7c0-.55.15-1.07.4-1.53l-.82-.8c-.44.68-.7 1.47-.7 2.33A4.43 4.43 0 0 0 7 11.36V13l2.25-2.18L7 8.64v1.63z" fill="#FFF" fill-rule="nonzero"/></svg>' +
                          '</div>' +
                          '<div class="acf-image-aspect-ratio-crop-modal-loading-text">' +
                          aiarc_translations.cropping_in_progress +
                          '</div>' +
                        '</div>';

          // prettier-ignore
          var error = '<div class="acf-image-aspect-ratio-crop-modal-error">' +
                        '<div class="acf-image-aspect-ratio-crop-modal-error-icon">' +
                        '<!-- Icon from https://github.com/google/material-design-icons -->' +
                        '<!-- Licensed under Apache License 2.0 -->' +
                        '<!-- Copyright (c) Google Inc. -->' +
                        '<svg width="22" height="22" viewBox="0 0 22 22" xmlns="http://www.w3.org/2000/svg"><path d="M1 20.14h20l-10-17-10 17zm10.9-2.69h-1.8v-1.79h1.8v1.8zm0-3.58h-1.8V10.3h1.8v3.58z" fill="#F44336" fill-rule="nonzero"/></svg>' +
                        '</div>' +
                        '<div class="acf-image-aspect-ratio-crop-modal-error-text">' +
                        aiarc_translations.cropping_failed +
                        '</div>' +
                      '</div>';

          $('.js-acf-image-aspect-ratio-crop-modal-footer-status').empty();
          $('.js-acf-image-aspect-ratio-crop-modal-footer-status').html(
            loading,
          );
          self.cropper.disable();

          let options = {};

          let url = null;

          if (window.aiarc_settings.rest_api_compat === '') {
            url = aiarcRestUrls().crop;
            options = {
              headers: {
                'X-Aiarc-Nonce': window.aiarc.nonce,
                'X-WP-Nonce': window.aiarc.wp_rest_nonce,
              },
            };
          }

          if (window.aiarc_settings.rest_api_compat === '1') {
            url = ajaxurl;
            data = qs.stringify({
              action: 'acf_image_aspect_ratio_crop_crop',
              data: JSON.stringify(data),
            });
          }

          axios
            .post(url, data, options)
            .then(response => {
              self.cropComplete(response.data);
              $('.js-acf-image-aspect-ratio-crop-crop').prop('disabled', false);
              $('.js-acf-image-aspect-ratio-crop-reset').prop(
                'disabled',
                false,
              );
              $('.js-acf-image-aspect-ratio-crop-modal-footer-status').empty();
            })
            .catch(response => {
              console.error(response);
              self.cropper.enable();
              $('.js-acf-image-aspect-ratio-crop-crop').prop('disabled', false);
              $('.js-acf-image-aspect-ratio-crop-reset').prop(
                'disabled',
                false,
              );
              $('.js-acf-image-aspect-ratio-crop-modal-footer-status').empty();
              $('.js-acf-image-aspect-ratio-crop-modal-footer-status').html(
                error,
              );
            });
        });
    },

    /*
     *  prepare
     *
     *  This function will prepare an object of attachment data
     *  selecting a library image vs embed an image via url return different data
     *  this function will keep the 2 consistent
     *
     *  @type	function
     *  @date	12/04/2016
     *  @since	5.3.8
     *
     *  @param	attachment (object)
     *  @return	data (object)
     */

    prepare: function(attachment) {
      // defaults
      attachment = attachment || {};

      // bail ealry if already valid
      if (attachment._valid) return attachment;

      // vars
      var data = {
        url: '',
        alt: '',
        title: '',
        caption: '',
        description: '',
        width: 0,
        height: 0,
      };

      // wp image or plain object with id/url
      if (attachment.id) {
        if (attachment.attributes) {
          data = attachment.attributes;
        } else {
          data = {
            id: attachment.id,
            url: attachment.url || '',
            alt: attachment.alt || '',
            title: attachment.title || '',
            caption: attachment.caption || '',
            description: attachment.description || '',
          };
        }
        if (attachment._inputValue !== undefined) {
          data._inputValue = attachment._inputValue;
        }
      }

      // valid
      data._valid = true;

      // return
      return data;
    },

    /*
     *  render
     *
     *  This function will render the UI
     *
     *  @type	function
     *  @date	12/04/2016
     *  @since	5.3.8
     *
     *  @param	attachment (obj)
     *  @return	n/a
     */

    render: function(data) {
      data = this.prepare(data);

      this.$img.attr({
        src: data.url,
        alt: data.alt,
        title: data.title,
      });

      var val = '';
      if (data._inputValue !== undefined) {
        val = data._inputValue;
      } else if (data.id) {
        val = data.id;
      }

      acf.val(this.$input, val);

      if (val) {
        this.$el.addClass('has-value');
      } else {
        this.$el.removeClass('has-value');
      }
    },

    /*
     *  add
     *
     *  event listener
     *
     *  @type	function
     *  @date	12/04/2016
     *  @since	5.3.8
     *
     *  @param	e (event)
     *  @return	n/a
     */

    add: function() {
      // reference
      var self = this,
        $field = this.$field;

      // get repeater
      var $repeater = acf.get_closest_field(this.$field, 'repeater');

      // popup
      var frame = acf.media.popup({
        title: acf._e('image', 'select'),
        mode: 'select',
        type: 'image',
        field: $field.data('key'),
        multiple: false,
        library: this.o.library,
        mime_types: this.o.mime_types,

        select: function(attachment, i) {
          // select / add another image field?
          if (i > 0) {
            // vars
            var key = $field.data('key'),
              $tr = $field.closest('.acf-row');

            // reset field
            $field = false;

            // find next image field
            $tr.nextAll('.acf-row:visible').each(function() {
              // get next $field
              $field = acf.get_field(key, $(this));

              // bail early if $next was not found
              if (!$field) return;

              // bail early if next file uploader has value
              if (
                $field
                  .find('.acf-image-uploader-aspect-ratio-crop.has-value')
                  .exists()
              ) {
                $field = false;
                return;
              }

              // end loop if $next is found
              return false;
            });

            // add extra row if next is not found
            if (!$field) {
              $tr = acf.fields.repeater.doFocus($repeater).add();

              // bail early if no $tr (maximum rows hit)
              if (!$tr) return false;

              // get next $field
              $field = acf.get_field(key, $tr);
            }
          }

          self.isFirstCrop = true;

          // Add original id attribute to the image so we can recrop it right away without saving the post
          $field
            .find('.acf-image-uploader-aspect-ratio-crop')
            .data('original-image-id', attachment.id)
            .attr('data-original-image-id', attachment.id);

          self.openModal({ attachment: attachment, field: $field });

          // render
          self.set('$field', $field).render(attachment);
        },
      });
    },

    changeCrop: function() {
      this.isFirstCrop = false;
      var originalImageId = $(this.$field)
        .find('.acf-image-uploader-aspect-ratio-crop')
        .data('original-image-id');

      let callback = response => {
        let attachment = new window.Backbone.Model(response.data);
        let $field = this.$field;
        this.openModal({ attachment: attachment, field: $field });
      };

      if (window.aiarc_settings.rest_api_compat === '') {
        axios
          .get(`${aiarcRestUrls().get}/${originalImageId}`)
          .then(response => callback(response));
      }

      if (window.aiarc_settings.rest_api_compat === '1') {
        let data = qs.stringify({
          action: 'acf_image_aspect_ratio_crop_get_attachment',
          data: JSON.stringify({ attachment_id: originalImageId }),
        });
        axios.post(ajaxurl, data).then(response => callback(response));
      }
    },

    /*
     *  edit
     *
     *  event listener
     *
     *  @type	function
     *  @date	12/04/2016
     *  @since	5.3.8
     *
     *  @param	e (event)
     *  @return	n/a
     */

    edit: function() {
      var $field = this.$field;
      var val = this.$input.parent().attr('data-original-image-id') || this.$input.val();
      if (!val) return;

      // If value is JSON (new format), parse to get attachment_id
      if (typeof val === 'string' && val.startsWith('{')) {
        try {
          var parsed = JSON.parse(val);
          val = parsed.attachment_id || val;
        } catch (e) {
          val = null;
        }
      }
      if (!val) return;

      acf.media.popup({
        title: acf._e('image', 'edit'),
        button: acf._e('image', 'update'),
        mode: 'edit',
        attachment: val,
      });
    },

    /*
     *  remove
     *
     *  event listener
     *
     *  @type	function
     *  @date	12/04/2016
     *  @since	5.3.8
     *
     *  @param	e (event)
     *  @return	n/a
     */

    remove: function() {
      // Remove all data attributes from the previous image
      this.$field
        .find('.acf-image-uploader-aspect-ratio-crop')
        .data('original-image-id', null)
        .attr('data-original-image-id', null)
        .data('coordinates', null)
        .attr('data-coordinates', null)
        .data('focal-point', null)
        .attr('data-focal-point', null);

      // vars
      var attachment = {};

      // add file to field
      this.render(attachment);
    },

    /*
     *  change
     *
     *  This function will update the hidden input when selecting a basic file to add basic validation
     *
     *  @type	function
     *  @date	12/04/2016
     *  @since	5.3.8
     *
     *  @param	e (event)
     *  @return	n/a
     */

    change: function(e) {
      //acf.fields.file.get_file_info(e.$el, this.$input);
    },

    escapeHandler: function(event) {
      if (event.key === 'Escape') {
        this.closeModal();
      }
    },

    getDefaultFocalPoint: function() {
      return { x: 50, y: 50 };
    },

    normalizeFocalPoint: function(x, y) {
      const clamp = value => {
        const num = parseFloat(value);
        if (Number.isNaN(num)) {
          return 50;
        }
        return Math.min(100, Math.max(0, Math.round(num * 10) / 10));
      };
      return {
        x: clamp(x),
        y: clamp(y),
      };
    },

    loadFocalPointFromField: function() {
      const $uploader = $(field).find('.acf-image-uploader-aspect-ratio-crop');
      let focal = $uploader.data('focal-point');

      if (!focal) {
        const attr = $uploader.attr('data-focal-point');
        if (attr) {
          try {
            focal = JSON.parse(attr);
          } catch (e) {
            focal = null;
          }
        }
      }

      if (!focal) {
        const inputVal = $(field)
          .find('input')
          .first()
          .val();
        if (inputVal && inputVal.startsWith('{')) {
          try {
            const parsed = JSON.parse(inputVal);
            focal = parsed.crop && parsed.crop.focal_point;
          } catch (e) {
            focal = null;
          }
        }
      }

      if (focal && typeof focal.x !== 'undefined' && typeof focal.y !== 'undefined') {
        return this.normalizeFocalPoint(focal.x, focal.y);
      }

      return this.getDefaultFocalPoint();
    },

    initFocalPoint: function() {
      this.destroyFocalPoint();
      this.focalPoint = this.loadFocalPointFromField();
      this.focalPointSize = 16;

      const label =
        (window.aiarc_translations && window.aiarc_translations.focal_point_label) ||
        'Drag to set focal point';

      this.$focalPoint = $(
        `<button type="button" class="acf-image-aspect-ratio-crop-focal-point js-acf-image-aspect-ratio-crop-focal-point" aria-label="${label}" title="${label}"></button>`,
      );

      const cropBox = this.cropper.cropper.querySelector('.cropper-crop-box');
      if (!cropBox) {
        return;
      }
      cropBox.appendChild(this.$focalPoint[0]);

      this.focalDragBound = false;
      this.isFocalDragging = false;
      this.bindFocalPointEvents();
      this.positionFocalPoint();

      const $image = $('.js-acf-image-aspect-ratio-crop-modal-image');
      $image.on(
        'ready.aiarcFocal crop.aiarcFocal cropmove.aiarcFocal cropend.aiarcFocal zoom.aiarcFocal',
        () => {
          if (!this.isFocalDragging) {
            this.positionFocalPoint();
          }
        },
      );
    },

    destroyFocalPoint: function() {
      if (this.$focalPoint && this.$focalPoint[0]) {
        this.$focalPoint[0].removeEventListener(
          'pointerdown',
          this.focalPointerDownBound,
        );
      }
      this.focalPointerDownBound = null;
      this.focalDragBound = false;
      this.isFocalDragging = false;
      $('.js-acf-image-aspect-ratio-crop-modal-image').off('.aiarcFocal');
      if (this.$focalPoint) {
        this.$focalPoint.remove();
        this.$focalPoint = null;
      }
    },

    bindFocalPointEvents: function() {
      if (!this.$focalPoint || this.focalDragBound) {
        return;
      }

      this.focalDragBound = true;
      const self = this;
      const el = this.$focalPoint[0];

      this.focalPointerDownBound = function(event) {
        if (event.button !== 0 && event.pointerType === 'mouse') {
          return;
        }

        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation();

        self.isFocalDragging = true;
        if (el.setPointerCapture && event.pointerId !== undefined) {
          el.setPointerCapture(event.pointerId);
        }

        const startX = event.clientX;
        const startY = event.clientY;
        const startFocal = { x: self.focalPoint.x, y: self.focalPoint.y };

        const onMove = moveEvent => {
          moveEvent.preventDefault();
          moveEvent.stopPropagation();

          const box = self.cropper.getCropBoxData();
          if (!box || box.width <= 0 || box.height <= 0) {
            return;
          }

          const deltaX = ((moveEvent.clientX - startX) / box.width) * 100;
          const deltaY = ((moveEvent.clientY - startY) / box.height) * 100;
          self.focalPoint = self.normalizeFocalPoint(
            startFocal.x + deltaX,
            startFocal.y + deltaY,
          );
          self.positionFocalPoint();
        };

        const onEnd = endEvent => {
          self.isFocalDragging = false;
          if (el.releasePointerCapture && endEvent.pointerId !== undefined) {
            try {
              el.releasePointerCapture(endEvent.pointerId);
            } catch (e) {
              // Pointer may already be released.
            }
          }
          document.removeEventListener('pointermove', onMove);
          document.removeEventListener('pointerup', onEnd);
          document.removeEventListener('pointercancel', onEnd);
        };

        document.addEventListener('pointermove', onMove);
        document.addEventListener('pointerup', onEnd);
        document.addEventListener('pointercancel', onEnd);
      };

      el.addEventListener('pointerdown', this.focalPointerDownBound);
    },

    positionFocalPoint: function() {
      if (!this.cropper || !this.$focalPoint) {
        return;
      }

      const box = this.cropper.getCropBoxData();
      if (!box || box.width <= 0 || box.height <= 0) {
        return;
      }

      const half = this.focalPointSize / 2;
      const cx = (this.focalPoint.x / 100) * box.width;
      const cy = (this.focalPoint.y / 100) * box.height;

      this.$focalPoint.css({
        left: cx - half,
        top: cy - half,
        zIndex: 2,
      });
    },

    resetFocalPoint: function() {
      this.focalPoint = this.getDefaultFocalPoint();
      this.positionFocalPoint();
    },

    openModal: function(data) {
      var url = data.attachment.attributes.url;
      var id = data.attachment.attributes.id;
      field = data.field;

      document.addEventListener('keydown', this.escapeHandlerBound);

      var aspectRatioWidth = $(field)
        .find('.acf-image-uploader-aspect-ratio-crop')
        .data('aspect_ratio_width');
      var aspectRatioHeight = $(field)
        .find('.acf-image-uploader-aspect-ratio-crop')
        .data('aspect_ratio_height');
      var cropType = $(field)
        .find('.acf-image-uploader-aspect-ratio-crop')
        .data('crop_type');
      var minWidth = $(field)
        .find('.acf-image-uploader-aspect-ratio-crop')
        .data('min_width');
      var minHeight = $(field)
        .find('.acf-image-uploader-aspect-ratio-crop')
        .data('min_height');

      var options = {
        aspectRatio: aspectRatioWidth / aspectRatioHeight,
        viewMode: 1,
        autoCropArea: 1,
        zoomable: false,
        checkCrossOrigin: false,
        checkOrientation: false,
        responsive: true,
      };

      if (cropType === 'pixel_size') {
        options.crop = function(event) {
          let width = event.detail.width;
          let height = event.detail.height;
          if (width < aspectRatioWidth || height < aspectRatioHeight) {
            this.cropper.setData({
              width: aspectRatioWidth,
              height: aspectRatioHeight,
            });
          }
        };
      }

      if (cropType === 'aspect_ratio' && minHeight !== 0 && minWidth !== 0) {
        options.crop = function(event) {
          let width = event.detail.width;
          let height = event.detail.height;
          if (width < minWidth || height < minHeight) {
            this.cropper.setData({
              width: minWidth,
              height: minHeight,
            });
          }
        };
      }

      let coordinates = $(field)
        .find('.acf-image-uploader-aspect-ratio-crop')
        .data('coordinates');

      if (coordinates) {
        options.data = coordinates;
      }

      // prettier-ignore
      $('body').append(`
<div class="acf-image-aspect-ratio-crop-backdrop">
  <div class="acf-image-aspect-ratio-crop-modal-wrapper">
    <div
      class="acf-image-aspect-ratio-crop-modal js-acf-image-aspect-ratio-crop-modal"
    >
      <div class="acf-image-aspect-ratio-crop-modal-heading">
        <div class="acf-image-aspect-ratio-crop-modal-heading-text">
          ${aiarc_translations.modal_title}
        </div>
        <button
          class="acf-image-aspect-ratio-crop-modal-heading-close js-acf-image-aspect-ratio-crop-cancel"
          aria-label="Close"
        >
          ${require('./close.svg?raw')}
        </button>
      </div>
      <div class="acf-image-aspect-ratio-crop-modal-image-container">
        <img
          class="acf-image-aspect-ratio-crop-modal-image js-acf-image-aspect-ratio-crop-modal-image"
          src="${url}"
        />
      </div>

      <div class="acf-image-aspect-ratio-crop-modal-footer">
        <div
          class="acf-image-aspect-ratio-crop-modal-footer-status js-acf-image-aspect-ratio-crop-modal-footer-status"
        ></div>
        <div class="acf-image-aspect-ratio-crop-modal-footer-buttons">
          <button
            class="aiarc-button aiarc-button-link acf-image-aspect-ratio-crop-reset js-acf-image-aspect-ratio-crop-reset"
          >
            ${require('./reset.svg?raw')}
            ${aiarc_translations.reset}
          </button>
          <button class="aiarc-button aiarc-button-default js-acf-image-aspect-ratio-crop-cancel">
            ${aiarc_translations.cancel}
          </button>
          <button
            class="aiarc-button aiarc-button-primary js-acf-image-aspect-ratio-crop-crop"
            data-id="${id}"
            data-aspect-ratio-height="${aspectRatioHeight}"
            data-aspect-ratio-width="${aspectRatioWidth}"
            data-crop-type="${cropType}"
          >
            ${aiarc_translations.crop}
          </button>
        </div>
      </div>
    </div>
  </div>
</div>
`);

      const cropperImage = $('.js-acf-image-aspect-ratio-crop-modal-image')[0];
      const self = this;
      const existingReady = options.ready;

      options.ready = function() {
        if (typeof existingReady === 'function') {
          existingReady.call(this);
        }
        self.initFocalPoint();
      };

      this.cropper = new Cropper(cropperImage, options);

      // Test helper
      window._acf_image_aspect_ratio_cropper = this.cropper;
    },

    cropComplete: function(data) {
      const focalJson = JSON.stringify(this.focalPoint || this.getDefaultFocalPoint());

      // Save coordinates so they are remembered even without saving the post first
      $(field)
        .find('.acf-image-uploader-aspect-ratio-crop')
        .data('coordinates', this.cropper.getData(true))
        .attr('data-coordinates', JSON.stringify(this.cropper.getData(true)))
        .data('focal-point', this.focalPoint)
        .attr('data-focal-point', focalJson);

      // Cropping successful - data is { attachment_id, original_url, crop, aspect_ratio }
      this.cropper.destroy();

      $(field)
        .find('input')
        .first()
        .val(JSON.stringify(data));

      const previewUrl = aiarcBuildPreviewUrl(data);

      const attachmentLike = {
        id: data.attachment_id,
        url: previewUrl,
        alt: '',
        title: '',
        caption: '',
        description: '',
        _inputValue: JSON.stringify(data),
      };

      this.render(attachmentLike);
      this.isFirstCrop = false;
      this.closeModal();
    },

    closeModal: function() {
      if (this.isFirstCrop) {
        // If it's the first time cropping an image, we don't want to
        // leave the incorrect aspect ratio image in the field
        acf.val(this.$input, '');
        this.render({});
      }
      $('.acf-image-aspect-ratio-crop-backdrop').remove();
      document.removeEventListener('keydown', this.escapeHandlerBound);
      this.destroyFocalPoint();
      if (this.cropper) {
        this.cropper.destroy();
      }
    },
  });

  /**
   *  initialize_field
   *
   *  This function will initialize the $field.
   *
   *  @date	30/11/17
   *  @since	5.6.5
   *
   *  @param	n/a
   *  @return	n/a
   */

  function initialize_field($el) {
    //$field.doStuff();
    //var $field = $el, $options = $el.find('.acf-field-image-aspect-ratio-crop');
  }

  /*
   *  ready & append (ACF5)
   *
   *  These two events are called when a field element is ready for initizliation.
   *  - ready: on page load similar to $(document).ready()
   *  - append: on new DOM elements appended via repeater field or other AJAX calls
   *
   *  @param	n/a
   *  @return	n/a
   */

  acf.add_action('ready_field/type=image_aspect_ratio_crop', initialize_field);
  acf.add_action('append_field/type=image_aspect_ratio_crop', initialize_field);
})(jQuery);
